mapper.delete:
delete from sup_platform_contact_rel
where platform_id = #{platformId}
  and contact_id = #{contactId}

mapper.select:
select count(1)
from sup_platform_contact_rel
where platform_id = #{platformId}
  and contact_id = #{contactId}

mapper.delete:
delete from sup_platform_contact_rel
where contact_id in (
    select contact_id
    from sup_contact
    where org_id = #{orgId}
)
